INSERT INTO `page_list` (`id`, `alias`, `page_title`, `page_content`, `status`) VALUES
(1, 'glowna', 'Katalog', '<h1>Sklep dla pasjonatów siatkówki</h1>\r\n<p>Znajdź piłki, koszulki i nakolanniki na kolejny trening.</p>\r\n\r\n<section id=\"clock-section\">\r\n    <p id=\"clock-display\"></p>\r\n    <button type=\"button\" id=\"clock-start\">Start zegara</button>\r\n    <button type=\"button\" id=\"clock-stop\">Stop zegara</button>\r\n</section>\r\n\r\n<section id=\"search-section\">\r\n    <label for=\"product-search\">Szukaj produktu:</label>\r\n    <input type=\"search\" id=\"product-search\" placeholder=\"Wpisz nazwę...\">\r\n    <div aria-live=\"polite\">\r\n        <p id=\"search-counter\">Liczba wyników: 3</p>\r\n        <p id=\"no-results\" hidden>Brak pasujących produktów.</p>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"products-grid\" aria-label=\"Katalog produktów\">\r\n    <article class=\"product-card\">\r\n        <h2>\r\n            <a href=\"index.php?idp=produkt\">Piłka siatkarska Mikasa V200W</a>\r\n        </h2>\r\n        <a href=\"index.php?idp=produkt\">\r\n            <img src=\"img/pilkamikasa.jpg\"\r\n                 alt=\"Oficjalna niebiesko-żółta piłka meczowa Mikasa V200W\"\r\n                 width=\"600\" height=\"600\">\r\n        </a>\r\n        <p>Oficjalna piłka meczowa FIVB z 18-panelowym układem aerodynamicznym.</p>\r\n        <p class=\"price\">399,00 zł</p>\r\n    </article>\r\n\r\n    <article class=\"product-card\">\r\n        <h2>Koszulka meczowa ZAKSA Kędzierzyn-Koźle</h2>\r\n        <img src=\"img/koszulkazaksa.jpg\"\r\n             alt=\"Niebieska domowa koszulka meczowa ZAKSA Kędzierzyn-Koźle\"\r\n             width=\"600\" height=\"600\">\r\n        <p>Oryginalna koszulka klubowa z oddychającego materiału technicznego.</p>\r\n        <p class=\"price\">229,00 zł</p>\r\n    </article>\r\n\r\n    <article class=\"product-card\">\r\n        <h2>Nakolanniki siatkarskie Mizuno</h2>\r\n        <img src=\"img/nakolannikimizuno.jpg\"\r\n             alt=\"Czarne nakolanniki siatkarskie Mizuno z pianką amortyzującą\"\r\n             width=\"600\" height=\"600\">\r\n        <p>Elastyczne ochraniacze na kolana skutecznie absorbujące uderzenia o parkiet.</p>\r\n        <p class=\"price\">89,00 zł</p>\r\n    </article>\r\n</section>\r\n\r\n<section id=\"lab3-demo\" aria-labelledby=\"lab3-title\">\r\n    <h2 id=\"lab3-title\">Animacje jQuery</h2>\r\n\r\n    <div class=\"animation-list\">\r\n        <button type=\"button\" class=\"animation-box\" id=\"anim-a\" aria-pressed=\"false\">\r\n            A — kliknij\r\n        </button>\r\n        <button type=\"button\" class=\"animation-box\" id=\"anim-b\">\r\n            B — najedź lub ustaw fokus\r\n        </button>\r\n        <button type=\"button\" class=\"animation-box\" id=\"anim-c\">\r\n            C — kliknij, aby powiększyć\r\n        </button>\r\n    </div>\r\n\r\n    <p id=\"steps-c\" role=\"status\">Liczba kroków C: 0</p>\r\n    <button type=\"button\" id=\"reset-ac\">Resetuj A i C</button>\r\n\r\n    <button type=\"button\" id=\"check-server\">Sprawdź serwer</button>\r\n    <p id=\"server-result\" role=\"status\"></p>\r\n</section>', 1),
(2, 'produkt', 'Produkt', '<h1>Piłka siatkarska Mikasa V200W</h1>\r\n\r\n<section class=\"product-details\">\r\n    <img src=\"img/pilkamikasa.jpg\"\r\n         alt=\"Oficjalna niebiesko-żółta piłka meczowa Mikasa V200W\"\r\n         width=\"600\" height=\"600\">\r\n\r\n    <p class=\"price\">Cena: 399,00 zł</p>\r\n\r\n    <p>\r\n        Mikasa V200W to <strong>oficjalna piłka meczowa FIVB</strong>,\r\n        wykorzystywana na najważniejszych turniejach międzynarodowych.\r\n        Zapewnia <em>doskonałą kontrolę</em> oraz stabilną trajektorię lotu.\r\n    </p>\r\n\r\n    <h2>Główne cechy produktu</h2>\r\n    <ul>\r\n        <li>Atest Międzynarodowej Federacji Piłki Siatkowej (FIVB Approved)</li>\r\n        <li>Układ 18 aerodynamicznie wyprofilowanych paneli</li>\r\n        <li>Podwójnie dimplowana powierzchnia z mikrowłókien stabilizująca tor lotu</li>\r\n        <li>Oryginalna kolorystyka zapewniająca znakomitą widoczność w hali</li>\r\n    </ul>\r\n\r\n    <p>\r\n        <a href=\"index.php?idp=kontakt\" class=\"button-link\">Zapytaj o produkt</a>\r\n    </p>\r\n\r\n    <h2>Parametry techniczne</h2>\r\n    <table>\r\n        <caption>Specyfikacja techniczna piłki siatkarskiej Mikasa V200W</caption>\r\n        <thead>\r\n            <tr>\r\n                <th scope=\"col\">Parametr</th>\r\n                <th scope=\"col\">Wartość</th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n            <tr>\r\n                <td>Rozmiar</td>\r\n                <td>5 (oficjalny)</td>\r\n            </tr>\r\n            <tr>\r\n                <td>Waga</td>\r\n                <td>260 – 280 g</td>\r\n            </tr>\r\n            <tr>\r\n                <td>Obwód</td>\r\n                <td>65 – 67 cm</td>\r\n            </tr>\r\n            <tr>\r\n                <td>Materiał</td>\r\n                <td>Syntetyczna skóra PU, mikrofibra</td>\r\n            </tr>\r\n        </tbody>\r\n    </table>\r\n</section>', 1),
(3, 'kontakt', 'Kontakt', '<h1>Formularz zapytania o produkt</h1>\r\n\r\n<p class=\"form-info\">\r\n    Podgląd lokalny. Formularz nie wysyła wiadomości.\r\n</p>\r\n\r\n<form id=\"kontakt-form\" action=\"index.php\" method=\"get\">\r\n    <input type=\"hidden\" name=\"idp\" value=\"kontakt\">\r\n\r\n    <p>\r\n        <label for=\"email\">Adres e-mail (pole wymagane):</label>\r\n        <input type=\"email\" id=\"email\" name=\"email\" required>\r\n    </p>\r\n\r\n    <p>\r\n        <label for=\"produkt\">Produkt (pole wymagane):</label>\r\n        <select id=\"produkt\" name=\"produkt\" required>\r\n            <option value=\"mikasa-v200w\">Piłka siatkarska Mikasa V200W</option>\r\n            <option value=\"koszulka-zaksa\">Koszulka meczowa ZAKSA Kędzierzyn-Koźle</option>\r\n            <option value=\"nakolanniki-mizuno\">Nakolanniki siatkarskie Mizuno</option>\r\n        </select>\r\n    </p>\r\n\r\n    <p>\r\n        <label for=\"ilosc\">Liczba sztuk (od 1 do 5, pole wymagane):</label>\r\n        <input type=\"number\" id=\"ilosc\" name=\"ilosc\"\r\n               min=\"1\" max=\"5\" step=\"1\" value=\"1\" required>\r\n    </p>\r\n\r\n    <p id=\"live-price\"></p>\r\n\r\n    <p>\r\n        <label for=\"wiadomosc\">\r\n            Treść zapytania (od 10 do 500 znaków, pole wymagane):\r\n        </label>\r\n        <textarea id=\"wiadomosc\" name=\"wiadomosc\"\r\n                  minlength=\"10\" maxlength=\"500\" rows=\"5\" required></textarea>\r\n        <span id=\"message-error\" style=\"color: red;\" hidden></span>\r\n    </p>\r\n\r\n    <p>\r\n        <button type=\"submit\">Sprawdź zapytanie</button>\r\n    </p>\r\n</form>\r\n\r\n<section id=\"order-summary\" hidden>\r\n    <h2>Podsumowanie zapytania</h2>\r\n    <p>Produkt: <span id=\"sum-product\"></span></p>\r\n    <p>Ilość: <span id=\"sum-qty\"></span></p>\r\n    <p>Wartość: <span id=\"sum-total\"></span></p>\r\n    <p>Wiadomość: <span id=\"sum-msg\"></span></p>\r\n</section>', 1),
(4, 'filmy', 'Filmy', '<section aria-labelledby=\"filmy-tytul\">\r\n    <h1 id=\"filmy-tytul\">Filmy o siatkówce</h1>\r\n\r\n    <p>\r\n        Kilka materiałów pokazujących podstawy gry w siatkówkę.\r\n        Filmy są w języku angielskim.\r\n    </p>\r\n\r\n    <article>\r\n        <h2>1. Podstawy odbicia dołem</h2>\r\n\r\n        <p>\r\n            Pozycja wyjściowa, ułożenie rąk i ruch podczas odbicia piłki.\r\n        </p>\r\n\r\n        <iframe\r\n            src=\"https://www.youtube.com/embed/gOgfoEGUDCA?autoplay=0\"\r\n            title=\"Podstawy odbicia dołem w siatkówce — poradnik\"\r\n            width=\"560\"\r\n            height=\"315\"\r\n            style=\"display: block; width: 100%; height: auto; aspect-ratio: 16 / 9; min-width: 200px; min-height: 200px; border: 0;\"\r\n            referrerpolicy=\"strict-origin-when-cross-origin\"\r\n            allow=\"encrypted-media; picture-in-picture; fullscreen\"\r\n            allowfullscreen>\r\n        </iframe>\r\n\r\n        <p>\r\n            <a href=\"https://www.youtube.com/watch?v=gOgfoEGUDCA\">\r\n                Obejrzyj poradnik odbicia dołem na YouTube\r\n            </a>\r\n        </p>\r\n    </article>\r\n\r\n    <article>\r\n        <h2>2. Zagrywka dla początkujących</h2>\r\n\r\n        <p>\r\n            Instrukcja wykonania zagrywki pokazana krok po kroku.\r\n        </p>\r\n\r\n        <iframe\r\n            src=\"https://www.youtube.com/embed/TBC_1c5kS3o?autoplay=0\"\r\n            title=\"Zagrywka w siatkówce dla początkujących — instrukcja\"\r\n            width=\"560\"\r\n            height=\"315\"\r\n            style=\"display: block; width: 100%; height: auto; aspect-ratio: 16 / 9; min-width: 200px; min-height: 200px; border: 0;\"\r\n            referrerpolicy=\"strict-origin-when-cross-origin\"\r\n            allow=\"encrypted-media; picture-in-picture; fullscreen\"\r\n            allowfullscreen>\r\n        </iframe>\r\n\r\n        <p>\r\n            <a href=\"https://www.youtube.com/watch?v=TBC_1c5kS3o\">\r\n                Obejrzyj poradnik zagrywki na YouTube\r\n            </a>\r\n        </p>\r\n    </article>\r\n\r\n    <article>\r\n        <h2>3. Odbicie, wystawa i zagrywka</h2>\r\n\r\n        <p>\r\n            Materiał przedstawiający podstawowe umiejętności siatkarskie:\r\n            odbicie, wystawę oraz zagrywkę.\r\n        </p>\r\n\r\n        <iframe\r\n            src=\"https://www.youtube.com/embed/eyrJdEUBYA8?autoplay=0\"\r\n            title=\"Podstawowe umiejętności siatkarskie — odbicie, wystawa i zagrywka\"\r\n            width=\"560\"\r\n            height=\"315\"\r\n            style=\"display: block; width: 100%; height: auto; aspect-ratio: 16 / 9; min-width: 200px; min-height: 200px; border: 0;\"\r\n            referrerpolicy=\"strict-origin-when-cross-origin\"\r\n            allow=\"encrypted-media; picture-in-picture; fullscreen\"\r\n            allowfullscreen>\r\n        </iframe>\r\n\r\n        <p>\r\n            <a href=\"https://www.youtube.com/watch?v=eyrJdEUBYA8\">\r\n                Obejrzyj materiał o podstawach siatkówki na YouTube\r\n            </a>\r\n        </p>\r\n    </article>\r\n</section>', 1),
(5, 'szkic', 'Strona robocza', '<h1>Strona robocza</h1><p>Ta treść nie jest jeszcze opublikowana.</p>', 0),
(7, 'o-sklepie', 'O sklepie', '<h1>O sklepie</h1><p>VolleyShop to projekt sklepu dla pasjonatów siatkówki.</p>', 1);
COMMIT;

